289	async function fetchAllEventPages(baseUrl, id, initialQuery = "") {
290	  const seen = [];
291	  const separator = initialQuery.includes("?") ? "&" : "?";
292	  const baseQuery = initialQuery === "" ? "" : initialQuery;
293	  let cursor = null;
294	  let pages = 0;
295	  for (;;) {
296	    const cursorPart = cursor === null ? "" : `${separator}cursor=${encodeURIComponent(cursor)}`;
297	    const page = await requestJson(baseUrl, `/scenarios/${id}/events${baseQuery}${cursorPart}`);
298	    assert.equal(page.status, 200);
299	    pages += 1;
300	    seen.push(...page.body.events);
301	    if (page.body.nextCursor === null) {
302	      break;
303	    }
304	    cursor = page.body.nextCursor;
305	    if (pages > 1000) {
306	      throw new Error("pagination did not terminate");
307	    }
308	  }
309	  return { events: seen, pages };
310	}
